mapper.select:
select bm_ingredient_weigh_record.storage_material_id, bm_material.name as material_name, bm_material.merge_code as material_merge_code, bm_storage_material_batch.material_batch_no as storage_material_batch_no, bm_storage_material.no as storage_material_no, ifnull(if(bm_ingredient_input_record.id is null, ifnull(bm_storage_material.available_quantity, 0) + ifnull(bm_storage_material.reserve_quantity, 0), bm_ingredient_input_record.quantity), 0) as quantity, if(bm_ingredient_input_record.id is null, bm_ingredient_weigh_record.unit_id, bm_ingredient_input_record.unit_id) as unit_id, bm_ingredient_input_record.importer_id, bm_ingredient_input_record.input_time, bm_ingredient_input_record.device_id, bm_ingredient_input_record.device_code, bm_ingredient_input_record.device_name, bm_ingredient_weigh_record.sign_status as weighSignStatus, bm_ingredient_input_record.component_instance_id from bm_ingredient_weigh_record left join bm_storage_material_batch on bm_ingredient_weigh_record.storage_material_batch_id = bm_storage_material_batch.id and bm_storage_material_batch.is_deleted = 0 left join bm_storage_material on bm_ingredient_weigh_record.storage_material_id = bm_storage_material.id and bm_storage_material.is_deleted = 0 left join bm_material on bm_storage_material.material_id = bm_material.id and bm_material.is_deleted = 0 left join bm_ingredient_input_record on bm_ingredient_weigh_record.storage_material_id = bm_ingredient_input_record.storage_material_id and bm_ingredient_input_record.is_deleted = 0 where bm_ingredient_weigh_record.weigh_type = 1 and bm_ingredient_weigh_record.ingredient_plan_id = #{ingredientPlanId}
and bm_material.id in
#{materialId}
